$esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}; $p=!empty($personnelRecord)?$personnelRecord:(object)array();
$v=function($f,$d='')use($p){return isset($p->$f)?$p->$f:$d;}; $sel=function($f,$o,$d='')use($v){$current=$v($f,$d); if($f==='personnel_type'&&$current==='')$current='Teaching'; if($f==='employment_status'&&$current==='')$current='Full-time'; return $current===$o?' selected':'';}; $edit=!empty($p->id); $benefits=array_filter(explode('|',(string)$v('benefits')));
$options=function($items,$field)use($sel){if($field==='work_assignment')array_unshift($items,'Teaching');foreach($items as $item)echo '<option'.$sel($field,$item).'>'.htmlspecialchars($item,ENT_QUOTES,'UTF-8').'</option>';};
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $edit?'Edit':'Add'; ?> Personnel</title><link href="<?= base_url(); ?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/icons.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/app.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/dashboard-unified.css" rel="stylesheet"><style>body{background:#f4f8fc}.shell{padding:22px 15px 36px}.hero{padding:28px 30px;border-radius:22px;color:#fff;background:linear-gradient(135deg,#272b8c,#3c40c6)}.hero h1{margin:0;color:#fff}.hero p{margin:8px 0 0;color:rgba(255,255,255,.8)}.card{margin-top:22px;border:0;border-radius:20px;box-shadow:0 16px 38px rgba(15,23,42,.08)}.section{margin:8px 0 20px;padding-bottom:11px;border-bottom:1px solid #e8ebf3;color:#272b8c;font-weight:800}.form-control{min-height:42px;border-radius:9px}.benefits{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:10px}.footer{position:static!important}</style></head><body class="dashboard-root-theme"><div id="wrapper"><?php include(__DIR__.'/includes/top-bar.php');include(__DIR__.'/includes/sidebar.php');?><div class="content-page"><div class="content"><main class="container-fluid dashboard-shell shell"><section class="hero"><a class="btn btn-sm btn-light mb-3" href="<?= base_url(); ?>Page/school_personnel">← Back to Personnel</a><h1><?= $edit?'Edit':'Add'; ?> Personnel</h1><p>Capture the information needed for the Annex D personnel profile.</p></section><section class="card"><form method="post" action="<?= base_url(); ?>Page/school_personnel_save"><div class="card-body p-4 p-md-5"><?php if($edit):?><input type="hidden" name="id" value="<?= (int)$p->id;?>"><?php endif;?><div class="section">Personal information</div><div class="form-row"><div class="form-group col-md-4"><label>First Name *</label><input class="form-control" name="first_name" required value="<?= $esc($v('first_name'));?>"></div><div class="form-group col-md-4"><label>Middle Name</label><input class="form-control" name="middle_name" value="<?= $esc($v('middle_name'));?>"></div><div class="form-group col-md-4"><label>Last Name *</label><input class="form-control" name="last_name" required value="<?= $esc($v('last_name'));?>"></div></div><div class="form-row"><div class="form-group col-md-4"><label>Employee No.</label><input class="form-control" name="employee_no" value="<?= $esc($v('employee_no'));?>"></div><div class="form-group col-md-4"><label>Sex</label><select class="form-control" name="sex"><option value="">Select</option><?php $options(array('Female','Male'),'sex');?></select></div><div class="form-group col-md-4"><label>Personnel Category</label><select class="form-control" name="personnel_type" id="personnelType"><?php $options(array('Administrative','Teaching','Non-Teaching'),'personnel_type');?></select><small class="form-text text-muted">Teaching is reported as full-time or part-time.</small></div></div><div class="section">Employment and assignment</div><div class="form-row"><div class="form-group col-md-4"><label>Position / Designation</label><input class="form-control" name="position_title" value="<?= $esc($v('position_title'));?>"></div><div class="form-group col-md-4 teaching"><label>Employment Status</label><select class="form-control" name="employment_status"><?php $options(array('Full-time','Part-time'),'employment_status');?></select></div><div class="form-group col-md-4"><label>Working Days / Week</label><select class="form-control" name="working_days_per_week"><option value="">Select days</option><?php foreach(range(1,7)as$n):?><option value="<?= $n;?>"<?= $sel('working_days_per_week',(string)$n);?>><?= $n;?> day<?= $n===1?'':'s';?></option><?php endforeach;?></select></div></div><div class="form-row"><div class="form-group col-md-6"><label>Teaching Load / Work Assignment</label><select class="form-control" name="work_assignment"><option value="">Select assignment</option><?php $options(array('Top Level/Executive Management','Principal/Assistant Principal','Administrative Officer','Registrar/Records Officer','HR Officer/Secretary','Finance Officer/Accountant','Coordinator','Core','Academic Electives','TechPro Electives','Administrative Staff','Finance and Accounting Staff','Guidance Counselor','Library Staff','IT / Technical Support','Maintenance / Janitorial / Security / Canteen Staff'),'work_assignment');?></select></div><div class="form-group col-md-6"><label>Salary Range</label><select class="form-control" name="salary_range"><option value="">Select salary range</option><?php $options(array('Below ₱10,000','₱10,000 – ₱14,999','₱15,000 – ₱19,999','₱20,000 – ₱29,999','₱30,000 – ₱39,999','₱40,000 – ₱49,999','₱50,000 and above'),'salary_range');?></select></div></div><div class="section">Qualifications</div><div class="form-row"><div class="form-group col-md-6"><label>Annex D Qualification Classification</label><select class="form-control" name="qualification_classification"><option value="">Select classification</option><?php $options(array('Civil Service Eligible','Other Qualification',"Bachelor's Degree","Master's Degree",'Specialist / Industry Expert','Professional','Technical','Other'),'qualification_classification');?></select></div><div class="form-group col-md-6"><label>Highest Educational Attainment</label><select class="form-control" name="highest_education"><option value="">Select attainment</option><?php $options(array('High School Graduate','Vocational/Technical Certificate','Associate Degree',"Bachelor's Degree","Master's Degree",'Doctorate Degree'),'highest_education');?></select></div></div><div class="form-row"><div class="form-group col-md-4"><label>Course / Degree</label><input class="form-control" name="education_course" value="<?= $esc($v('education_course'));?>"></div><div class="form-group col-md-4"><label>Major / Specialization</label><input class="form-control" name="major_specialization" value="<?= $esc($v('major_specialization'));?>"></div><div class="form-group col-md-4 teaching"><label>PRC License Number <span class="text-danger js-prc-required d-none">*</span></label><input class="form-control" id="prcLicenseNo" name="prc_license_no" value="<?= $esc($v('prc_license_no'));?>"></div></div><div class="custom-control custom-checkbox mb-4 teaching"><input class="custom-control-input" type="checkbox" id="licensed" name="licensed" value="1"<?= !empty($p->licensed)?' checked':'';?>><label class="custom-control-label" for="licensed">Licensed Teacher (LET passer)</label></div><div class="section">Benefits and contact information</div><div class="form-group"><label>Benefits <small class="text-muted">(select all that apply)</small></label><div class="benefits"><?php foreach(array('SSS','GSIS','PhilHealth','Pag-IBIG Fund','13th Month Pay','Leave Benefits','Health Insurance','Rice Allowance')as$b):?><div class="custom-control custom-checkbox"><input class="custom-control-input" type="checkbox" id="b<?= md5($b);?>" name="benefits[]" value="<?= $esc($b);?>"<?= in_array($b,$benefits,true)?' checked':'';?>><label class="custom-control-label" for="b<?= md5($b);?>"><?= $esc($b);?></label></div><?php endforeach;?></div></div><div class="form-row"><div class="form-group col-md-6"><label>Email</label><input class="form-control" type="email" name="email" value="<?= $esc($v('email'));?>"></div><div class="form-group col-md-6"><label>Mobile Number</label><input class="form-control" name="mobile_no" value="<?= $esc($v('mobile_no'));?>"></div></div></div><div class="card-footer bg-white border-0 text-right p-4"><a class="btn btn-light mr-2" href="<?= base_url();?>Page/school_personnel">Cancel</a><button class="btn btn-primary" type="submit"><i class="mdi mdi-content-save-outline"></i> <?= $edit?'Save Changes':'Save Personnel';?></button></div></form></section></main></div></div></div><script src="<?= base_url();?>assets/js/vendor.min.js"></script><script>document.addEventListener('DOMContentLoaded',function(){var t=document.getElementById('personnelType'),licensed=document.getElementById('licensed'),prc=document.getElementById('prcLicenseNo');function r(){var teaching=t.value==='Teaching';document.querySelectorAll('.teaching').forEach(function(e){e.style.display=teaching?'':'none';});var required=teaching&&licensed.checked;prc.required=required;document.querySelectorAll('.js-prc-required').forEach(function(e){e.classList.toggle('d-none',!required);});}t.addEventListener('change',r);licensed.addEventListener('change',r);r();});</script></body></html>
